<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Finance,Registry,Settings,ContributionInvoices,ContributionMail,DonationForms};
$n=0;function ok(bool $v,string $m):void{global $n;if(!$v)throw new RuntimeException($m);++$n;echo "PASS $m\n";}
function denied(callable $f,string $m):void{try{$f();}catch(DomainException){ok(true,$m);return;}throw new RuntimeException($m);}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','A'),('b','B');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','members',1),('reader','a','member',0),('other','b','members',1)");
$f=new Finance($db,'admin');$s=new Settings($db,'admin');$registry=new Registry($db,'admin');$key=fn()=>bin2hex(random_bytes(16));$bank=$f->createAccount('Bank','offline','0','2026-01-01');
$entry=fn($amount='48')=>$f->createEntry(['kind'=>'contribution','description'=>'Contribution','amount'=>$amount,'document_date'=>'2026-08-01','due_date'=>'2026-08-31','category'=>'membership'],$key());
$payment=fn($description,$amount='48')=>$f->createTransaction(['account'=>$bank,'booked_on'=>'2026-08-02','direction'=>'income','amount'=>$amount,'description'=>$description],$key());
$id=$entry();$ref=$f->entry($id)['display_number'];$tx=$payment('Payment '.$ref);ok($f->entry($id)['payment_state']==='paid','exact invoice and amount auto allocate');ok(count($f->allocations($id))===1,'one allocation');ok($f->matchRecordedTransactions()===0,'repeat automatic run is idempotent');
$l=$f->allocations($id)[0];$f->releaseAllocation($l['id'],2,2,'Correction');ok($f->matchRecordedTransactions()===0,'released allocation remains manual');
$second=$entry();$ref2=$f->entry($second)['display_number'];$partial=$payment($ref2,'24');ok($f->transactionDetail($partial)['remaining_cents']===2400,'partial payment remains unresolved');
$ambiguous=$payment($ref.' '.$ref2);ok($f->transactionDetail($ambiguous)['remaining_cents']===4800,'multiple references remain unresolved');
$suffix=$payment($ref2.'9');ok($f->transactionDetail($suffix)['remaining_cents']===4800,'substring references never match');
$name=$payment('Same name');ok($f->transactionDetail($name)['remaining_cents']===4800,'name and amount alone never match');
$person=$registry->saveContact(null,0,'person','Member','member@example.invalid','Address');$membership=$registry->addMembership($person,'MEM-123','aktiv','2026-01-01');$annual=$f->createAnnualContribution($person,2026,'');$memberTx=$payment('Contribution MEM-123');ok($f->entry($annual)['payment_state']==='paid','unique member number and amount allocate');
$next=$f->createAnnualContribution($person,2027,'');$third=$entry();$conflict=$payment($f->entry($third)['display_number'].' MEM-123');ok($f->transactionDetail($conflict)['remaining_cents']===4800,'conflicting invoice/member reference remains unresolved');
denied(fn()=>(new Finance($db,'reader'))->matchRecordedTransactions(),'read-only actor cannot auto allocate');
$bs=$s->section('bank');$bs['data']=array_replace($bs['data'],['account_id'=>$bank,'holder'=>'Test','iban'=>'DE89370400440532013000']);$s->save('bank',$bs['data'],0);ok($s->section('bank')['data']['account_id']===$bank,'bank settings link own finance account');
$foreign=(new Finance($db,'other'))->createAccount('Other','offline','0','2026-01-01');denied(fn()=>$s->save('bank',array_replace($bs['data'],['account_id'=>$foreign]),1),'foreign bank link rejected');
$don=$f->createEntry(['kind'=>'donation','description'=>'Donation','counterparty'=>'Free text','amount'=>'100','document_date'=>'2026-08-01','due_date'=>'2026-08-31','category'=>'donations'],$key());$f->assignDonationContact('entry',$don,1,$person);ok($f->donationContact('entry',$don)['id']===$person,'donation links explicit contact');
$forms=new DonationForms($db,'admin');$draft=$forms->defaults('money',$don);$draft['amount']='100';$draft['donated_on']='2026-08-01';denied(fn()=>$forms->build($draft),'unpaid source cannot become paid donation draft');
$part=$payment('Donation part','25');$alloc=$f->allocate($part,1,$don,2,'25',$key());$draft=$forms->defaults('money',$don);ok($draft['amount']==='25,00'&&$draft['donated_on']==='2026-08-02','donation defaults use actual paid amount/date');ok(str_contains($draft['donor'],'Address'),'donation gets explicit contact address');
denied(fn()=>$forms->build(array_replace($draft,['amount'=>'100'])),'cannot inflate paid donation amount');denied(fn()=>$forms->build(array_replace($draft,['donated_on'=>'2026-08-01'])),'cannot change actual payment date');
$snapshot=$forms->build($draft);ok($snapshot['payment_ids']===[$alloc],'donation draft retains payment provenance');
$template=$s->section('texts_contributions');$template['data']['invoice']['subject']='Custom {{RECHNUNGSNUMMER}}';$template['data']['invoice']['message']='Due {{ZAHLBETRAG}} to {{VEREINS_IBAN}}';$template['data']['reminder']['message']='Reminder {{ZAHLBETRAG}}';$s->save('texts_contributions',$template['data'],0);
(new ContributionInvoices($db,'admin'))->issue($next);$mail=ContributionMail::build($db,'a',$next,'invoice');ok(str_starts_with($mail['subject'],'Custom ')&&str_contains($mail['text'],'Due 48,00 €'),'invoice mail uses saved template');ok(str_contains($mail['text'],'DE89370400440532013000'),'mail uses issued invoice bank snapshot');
$reminder=ContributionMail::build($db,'a',$next,'reminder');ok(str_contains($reminder['text'],'Reminder 48,00 €'),'reminder uses saved template');
$two=$registry->saveContact(null,0,'person','Two years','','');$registry->addMembership($two,'MEM-222','aktiv','2025-01-01');$f->createAnnualContribution($two,2025,'');$f->createAnnualContribution($two,2026,'');$twoTx=$payment('MEM-222');ok($f->transactionDetail($twoTx)['remaining_cents']===4800,'multiple open years for a member remain unresolved');
$parent=$registry->saveContact(null,0,'person','Family parent','','');$child=$registry->saveContact(null,0,'person','Family child','','');$registry->addMembership($parent,'MEM-301','aktiv','2026-01-01');$registry->addMembership($child,'MEM-302','aktiv','2026-01-01');$registry->assignFamily($parent,'','new','Family');$family=$registry->family($parent);$registry->assignFamily($child,'',$family['id']);$familyEntry=$f->createAnnualContribution($parent,2026,$family['id']);$payment('MEM-302','72');ok($f->entry($familyEntry)['payment_state']==='paid','family child member number matches shared family contribution');
$later=$f->createTransaction(['account'=>$bank,'booked_on'=>'2026-08-03','direction'=>'income','amount'=>'10','description'=>'Later donation'],$key());$laterAllocation=$f->allocate($later,1,$don,3,'10',$key());$combined=$forms->defaults('money',$don);ok($combined['amount']==='35,00'&&$combined['donated_on']==='','different payment dates are not presented as one invented date');denied(fn()=>$forms->build(array_replace($combined,['donated_on'=>'2026-08-03'])),'combined payment cannot use last date for earlier payment');$selected=$forms->defaults('money',$don,$laterAllocation);ok($selected['amount']==='10,00'&&$selected['donated_on']==='2026-08-03','single allocation selects exact amount and date');ok($forms->build($selected)['payment_ids']===[$laterAllocation],'selected payment provenance retained');
ok((\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)[0]??false)===false,'linked data retains foreign keys');
echo "$n linkage integration checks passed; no bank or mail calls\n";
